{"research_date": "2026-09-10", "pairs": [{"pair_id": "conflict_9d112ef406d37036ebdde5f5", "claim_ids": ["claim_1d47f2d2eb42cda1c3bd1be3", "claim_413115ff16b9f70182d6bfc0"], "query_ids": ["q_383"], "claims": [{"claim_id": "claim_1d47f2d2eb42cda1c3bd1be3", "quote": "Electric vehicles (EVs) – August 1, 2024, increase from 25% to 100%", "url": "https://www.millercanfield.com/resources-USTR-Starts-New-Section-301-Tariffs.html", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "Section 301 tariffs", "affected_product": "Electric vehicles (EVs)", "duty_rate": "100%", "effective_date": "August 1, 2024"}}, {"claim_id": "claim_413115ff16b9f70182d6bfc0", "quote": "With a 100% tariff (on top of existing 2.5% auto duties), Chinese EVs like BYD or NIO are mathematically locked out of the US market.", "url": "https://energy-solutions.co/policy-intelligence/trade-and-tariffs/us-section-301-tariffs-ev-batteries", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"company": "BYD or NIO", "duty_rate": "100%"}}]}, {"pair_id": "conflict_fe303ff1b43a1673832e7956", "claim_ids": ["claim_6b3a29090bee35b63044f2f9", "claim_7c2241f51b2e9772ff6e6fd6"], "query_ids": ["q_383"], "claims": [{"claim_id": "claim_6b3a29090bee35b63044f2f9", "quote": "Effective with respect to entries on or after September 27, 2024, articles the product of China, as provided for in subdivision (b) of U.S. note 31 to this subchapter The duty provided in the applicable subheading + 25%", "url": "https://www.federalregister.gov/documents/2024/09/18/2024-21217/notice-of-modification-chinas-acts-policies-and-practices-related-to-technology-transfer", "kind": "full_document", "publisher_type": "official_trade_authority", "fields": {"country_of_origin": "China", "effective_date": "September 27, 2024"}}, {"claim_id": "claim_7c2241f51b2e9772ff6e6fd6", "quote": "Effective on January 1, 2025, note 20(b) to subchapter III of chapter 99 is modified by deleting the following 8-digit subheading numbers: (1) 8541.21.00 (2) 8541.29.00 (3) 8541.30.00 (4) 8541.49.70 (5) 8541.49.80 (6) 8541.49.95 (7) 8541.51.00 (8) 8541.59.00 (9) 8541.90.00", "url": "https://www.federalregister.gov/documents/2024/09/18/2024-21217/notice-of-modification-chinas-acts-policies-and-practices-related-to-technology-transfer", "kind": "full_document", "publisher_type": "official_trade_authority", "fields": {"effective_date": "January 1, 2025"}}]}, {"pair_id": "conflict_cd0cd8cb61db598d23719088", "claim_ids": ["claim_6b3a29090bee35b63044f2f9", "claim_a7e090ece5af2d50c1d8a6ca"], "query_ids": ["q_383"], "claims": [{"claim_id": "claim_6b3a29090bee35b63044f2f9", "quote": "Effective with respect to entries on or after September 27, 2024, articles the product of China, as provided for in subdivision (b) of U.S. note 31 to this subchapter The duty provided in the applicable subheading + 25%", "url": "https://www.federalregister.gov/documents/2024/09/18/2024-21217/notice-of-modification-chinas-acts-policies-and-practices-related-to-technology-transfer", "kind": "full_document", "publisher_type": "official_trade_authority", "fields": {"country_of_origin": "China", "effective_date": "September 27, 2024"}}, {"claim_id": "claim_a7e090ece5af2d50c1d8a6ca", "quote": "Tariff increases in 2024 are applicable with respect to products that are entered for consumption, or withdrawn from warehouse for consumption, on or after September 27, 2024.", "url": "https://www.federalregister.gov/documents/2024/09/18/2024-21217/notice-of-modification-chinas-acts-policies-and-practices-related-to-technology-transfer", "kind": "full_document", "publisher_type": "official_trade_authority", "fields": {"tariff_program": "section 301 duties", "effective_date": "September 27, 2024"}}]}, {"pair_id": "conflict_386bc22924cccdd1209a81fa", "claim_ids": ["claim_0e39bdce452c6d9176025910", "claim_4cf1f8e4cc34ded12545d2a9"], "query_ids": ["q_384"], "claims": [{"claim_id": "claim_0e39bdce452c6d9176025910", "quote": "This change follows Executive Orders issued on February 1, 2025, targeting the synthetic opioid supply chain.", "url": "https://geodis.com/us-en/resources/customs-corner/entry-summary-order-reporting-multiple-hts-ace", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "Executive Orders", "affected_product": "synthetic opioid supply chain"}}, {"claim_id": "claim_4cf1f8e4cc34ded12545d2a9", "quote": "The update includes the reporting of Chapter 99 HTS for products of China and Hong Kong which were implemented February 1, 2025, in the Executive Order to the Internal Emergency Economic Powers Act (IEEPA).", "url": "https://geodis.com/us-en/resources/customs-corner/entry-summary-order-reporting-multiple-hts-ace", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "Executive Order to the Internal Emergency Economic Powers Act (IEEPA)", "country_of_origin": "China and Hong Kong", "effective_date": "February 1, 2025"}}]}, {"pair_id": "conflict_63788866877f7e62cf5d3336", "claim_ids": ["claim_9cf2db37e6bd7260bbca3e6c", "claim_a8eb2c95eba4f993a807ce8f"], "query_ids": ["q_384"], "claims": [{"claim_id": "claim_9cf2db37e6bd7260bbca3e6c", "quote": "On February 5, 2025, President Donald Trump issued an Executive Order amending a previous order from February 1, 2025, which had removed the de minimis exemption for goods of China and Hong Kong valued under $800.", "url": "https://geodis.com/us-en/resources/customs-corner/entry-summary-order-reporting-multiple-hts-ace", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "Executive Order", "effective_date": "February 5, 2025"}}, {"claim_id": "claim_a8eb2c95eba4f993a807ce8f", "quote": "The amendment reinstates the de minimis exemption temporarily, allowing duty-free entry for eligible low-value packages until the Secretary of Commerce confirms that adequate systems are in place to efficiently process and collect the applicable tariffs.", "url": "https://geodis.com/us-en/resources/customs-corner/entry-summary-order-reporting-multiple-hts-ace", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "de minimis exemption"}}]}, {"pair_id": "conflict_abd81ed4ed78dfcfb4efb902", "claim_ids": ["claim_06e4f24d089cc4ea60701694", "claim_836d19a7c9095abcbe2c8721"], "query_ids": ["q_385"], "claims": [{"claim_id": "claim_06e4f24d089cc4ea60701694", "quote": "In September, the outgoing administration of President Joe Biden finalized a proposal to increase the Section 301 import duty on Chinese-made lithium-ion batteries from 7.5% to 25%, beginning on Jan. 1, 2026.", "url": "https://www.utilitydive.com/news/us-battery-storage-lfp-nmc-market-possible-significant-tariff-impacts-clean-energy/737317", "kind": "search_snippet", "publisher_type": "secondary_or_unverified_publisher", "fields": {"company": "President Joe Biden", "tariff_program": "Section 301 import duty", "affected_product": "Chinese-made lithium-ion batteries", "duty_rate": "25%", "effective_date": "Jan. 1, 2026", "reported_policy_status": "proposal"}}, {"claim_id": "claim_836d19a7c9095abcbe2c8721", "quote": "the combined rate will reach a high of 57.4% starting April 9, 2025", "url": "https://www.lithiumforkliftbattery.com/impact-of-usa-tariff-increase-on-lifepo4-batteries.html", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"duty_rate": "57.4%", "effective_date": "April 9, 2025"}}]}, {"pair_id": "conflict_9b8da32607ca0949e0bf4260", "claim_ids": ["claim_0f5cf3580948fd8d062a4c01", "claim_972e84ea7ca2c0d3db6e673d"], "query_ids": ["q_385"], "claims": [{"claim_id": "claim_0f5cf3580948fd8d062a4c01", "quote": "Lithium-ion batteries are classified under HTS 8507.60 with a base duty rate of 3.4%. Section 301 tariffs on Chinese-origin lithium-ion batteries add 25%, bringing the effective rate to 28.4% for Chinese imports.", "url": "https://ustariffrates.com/products/batteries", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "Section 301 tariffs on Chinese-origin lithium-ion batteries add 25%", "duty_rate": "28.4%"}}, {"claim_id": "claim_972e84ea7ca2c0d3db6e673d", "quote": "Yes, EV battery cells and packs from China face Section 301 tariffs of 25% on top of the base 3.4% duty.", "url": "https://ustariffrates.com/products/batteries", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "Section 301 tariffs", "duty_rate": "25%"}}]}, {"pair_id": "conflict_015f026dfd0b7141f2283ee3", "claim_ids": ["claim_836d19a7c9095abcbe2c8721", "claim_981aea59abf6bb7361b4d6fa"], "query_ids": ["q_385"], "claims": [{"claim_id": "claim_836d19a7c9095abcbe2c8721", "quote": "the combined rate will reach a high of 57.4% starting April 9, 2025", "url": "https://www.lithiumforkliftbattery.com/impact-of-usa-tariff-increase-on-lifepo4-batteries.html", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"duty_rate": "57.4%", "effective_date": "April 9, 2025"}}, {"claim_id": "claim_981aea59abf6bb7361b4d6fa", "quote": "As of April 2025, the total tariffs range from approximately 70% to over 170%, depending on the battery type and classification.", "url": "https://www.lithiumforkliftbattery.com/impact-of-usa-tariff-increase-on-lifepo4-batteries.html", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "total tariffs", "effective_date": "April 2025"}}]}, {"pair_id": "conflict_17484913dded7be198487bbb", "claim_ids": ["claim_06e4f24d089cc4ea60701694", "claim_ecfebaf16a81f49195149cc1"], "query_ids": ["q_385"], "claims": [{"claim_id": "claim_06e4f24d089cc4ea60701694", "quote": "In September, the outgoing administration of President Joe Biden finalized a proposal to increase the Section 301 import duty on Chinese-made lithium-ion batteries from 7.5% to 25%, beginning on Jan. 1, 2026.", "url": "https://www.utilitydive.com/news/us-battery-storage-lfp-nmc-market-possible-significant-tariff-impacts-clean-energy/737317", "kind": "search_snippet", "publisher_type": "secondary_or_unverified_publisher", "fields": {"company": "President Joe Biden", "tariff_program": "Section 301 import duty", "affected_product": "Chinese-made lithium-ion batteries", "duty_rate": "25%", "effective_date": "Jan. 1, 2026", "reported_policy_status": "proposal"}}, {"claim_id": "claim_ecfebaf16a81f49195149cc1", "quote": "The incoming administration of President-elect Donald Trump has proposed further increasing the duty as high as 60%, CEA said.", "url": "https://www.utilitydive.com/news/us-battery-storage-lfp-nmc-market-possible-significant-tariff-impacts-clean-energy/737317", "kind": "search_snippet", "publisher_type": "secondary_or_unverified_publisher", "fields": {"company": "President-elect Donald Trump", "tariff_program": "duty", "duty_rate": "60%"}}]}, {"pair_id": "conflict_59568ad8e74e69ead80b6b81", "claim_ids": ["claim_6cd407d9bd052632da702c4a", "claim_db369d8c70d0bc9a717c0baa"], "query_ids": ["q_386"], "claims": [{"claim_id": "claim_6cd407d9bd052632da702c4a", "quote": "- A Section 301 tariff targeting Chinese imports, currently at 7.5%, is scheduled to rise to 25% by January 2026.", "url": "https://www.ufinebattery.com/blog/comprehensive-analysis-of-u-s-tariffs-on-chinese-lithium-batteries", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "Section 301 tariff", "duty_rate": "7.5%", "effective_date": "January 2026"}}, {"claim_id": "claim_db369d8c70d0bc9a717c0baa", "quote": "At minimum, such imports from China could result in a tariff exceeding 145% ad valorem. This tariff, whatever it may be when you import your lithium batteries, will be added on to Section 301 tariffs.", "url": "https://usacustomsclearance.com/process/importing-lithium-batteries", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"duty_rate": "exceeding 145% ad valorem"}}]}]}

